contract InvMutTest {
    C c;
    Neuron n;

    constructor(C _c) {
        c = _c;
    }

    // We take parameters: tokenId to buy, quantity to mint, and an address neuronAddress that points
    // to the Neuron token contract which c will be instantiated with. We also take a treasury address
    // for the Neuron instance constructor and an owner address used when deploying Neuron externally
    // by the harness. However the checker deploys c already; we only need to point to an existing
    // Neuron address. To keep inputs minimal we accept neuronAddress and tokenId, quantity.
    function run(address neuronAddress, uint256 tokenId, uint256 quantity) public payable {
        require(quantity > 0);
        // attach to the Neuron instance that C is expected to use
        n = Neuron(neuronAddress);

        // Observe pre-state: buyer is address(this)
        uint256 buyerNRNBefore = n.balanceOf(address(this));
        uint256 tokenBalanceBefore = c.balanceOf(address(this), tokenId);
        uint256 remainingSupplyBefore = c.remainingSupply(tokenId);

        // Also get item's price and finiteSupply flag via public storage accessors
        // allGameItemAttributes is public array; but there is no direct accessor for struct fields
        // So we can observe remainingSupply (itemsRemaining) and uniqueTokensOutstanding to ensure tokenId exists
        uint256 uniqueBefore = c.uniqueTokensOutstanding();

        // We will attempt the mint call on c and record whether it reverted.
        bool reverted = false;
        try c.mint(tokenId, quantity) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe post-state
        uint256 buyerNRNAfter = n.balanceOf(address(this));
        uint256 tokenBalanceAfter = c.balanceOf(address(this), tokenId);
        uint256 remainingSupplyAfter = c.remainingSupply(tokenId);
        uint256 uniqueAfter = c.uniqueTokensOutstanding();

        // General rule: if mint did NOT revert then:
        // - uniqueTokensOutstanding is unchanged (minting tokens shouldn't create new token types)
        // - buyer's token balance increased by quantity
        // - buyer's NRN balance decreased by some non-negative amount (price) (we assert decreased by at least 1 if price>0)
        // - if remainingSupplyBefore != remainingSupplyAfter then remainingSupplyAfter = remainingSupplyBefore - quantity
        // If mint reverted then no balances changed (NRN and token balances remain same) and unique count unchanged.

        assert(
            // unique tokens unchanged always
            uniqueBefore == uniqueAfter &&

            (
                // case: reverted -> no changes in observed balances/supply
                (reverted && buyerNRNBefore == buyerNRNAfter && tokenBalanceBefore == tokenBalanceAfter && remainingSupplyBefore == remainingSupplyAfter)
                ||
                // case: succeeded -> token balance increased by quantity and NRN decreased or unchanged (NRN decrease indicates payment)
                (!reverted && tokenBalanceAfter == tokenBalanceBefore + quantity && buyerNRNAfter <= buyerNRNBefore &&
                    // if supply is finite, assert it decreased exactly by quantity; if finite supply was false, remainingSupply may be unchanged
                    ( (remainingSupplyBefore >= quantity && remainingSupplyAfter == remainingSupplyBefore - quantity) || (remainingSupplyBefore == remainingSupplyAfter) )
                )
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function taking inputs for item properties and attempting to create an item
    function run(string calldata name_, string calldata tokenURI, bool finiteSupply, bool transferable, uint256 itemsRemaining, uint256 itemPrice, uint16 dailyAllowance) public payable {
        // require caller is admin: the deployed InvMutTest is not admin by default, but the checker deploys C fresh
        // so we must rely on adjusting admin: contract owner at deployment is this test's deployer (the checker)
        // The requirement in C.createGameItem is isAdmin[msg.sender], so we must make msg.sender admin.
        // However, we cannot call adjustAdminAccess because only owner can call it. The checker deploys C with ownerAddress set to some address
        // But the InvMutTest runs with msg.sender equal to this contract; per constraints the test contract deployed c originally, so this contract is the owner and isAdmin is true.
        // So no precondition needed.

        uint256 beforeCount = c.uniqueTokensOutstanding();

        // call createGameItem which mutates state: must be top-level
        c.createGameItem(name_, tokenURI, finiteSupply, transferable, itemsRemaining, itemPrice, dailyAllowance);

        uint256 afterCount = c.uniqueTokensOutstanding();

        // The new token id should be beforeCount (since they push and then increment _itemCount)
        uint256 newId = beforeCount;

        // observe uri and transferability effect via attempting a transfer which should revert if non-transferable
        string memory observedURI = c.uri(newId);

        bool transferReverted;
        // Prepare dummy addresses: use address(this) (InvMutTest) and another address (use address(0x1234))
        // Need to mint some tokens to allow transfer; createGameItem does not mint, so safeTransferFrom will revert due to insufficient balance if transferable. To observe transferability we attempt a transfer which should revert for non-transferable even before balance checks because safeTransferFrom in C enforces transferable first.
        // We call safeTransferFrom and catch revert to detect whether transferability guard triggered.
        try c.safeTransferFrom(address(0x0), address(0x1), newId, 1, "") {
            transferReverted = false;
        } catch {
            transferReverted = true;
        }

        // If transferable==false then safeTransferFrom should revert (transferReverted==true).
        // If transferable==true then safeTransferFrom might still revert for other reasons (balance/approval), so we only assert implication in one direction: non-transferable implies revert happened.

        assert(afterCount == beforeCount + 1 && (bytes(tokenURI).length == 0 ? (keccak256(bytes(observedURI)) == keccak256(bytes(c.uri(newId)))) : (keccak256(bytes(observedURI)) == keccak256(bytes(tokenURI)))) && (transferable == false ? transferReverted == true : true));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Create a single game item and check uniqueTokensOutstanding increased by 1
    // and that uri(newId) equals tokenURI when tokenURI is non-empty.
    function run(string calldata name_, string calldata tokenURI, bool finiteSupply, bool transferable, uint256 itemsRemaining, uint256 itemPrice, uint16 dailyAllowance) public payable {
        // No precondition needed: the deployer of C in the harness is the owner and thus an admin.
        uint256 before = c.uniqueTokensOutstanding();

        // top-level state-changing call
        c.createGameItem(name_, tokenURI, finiteSupply, transferable, itemsRemaining, itemPrice, dailyAllowance);

        uint256 after = c.uniqueTokensOutstanding();
        uint256 newId = before; // new token id should be the previous count

        string memory observed = c.uri(newId);

        // If tokenURI is non-empty, the contract should return it for the new token id; otherwise it returns the base uri (super.uri)
        bool tokenURINonEmpty = bytes(tokenURI).length > 0;

        // Assert the general rule: count increased by 1, and when tokenURI provided, uri(newId)==tokenURI
        assert(after == before + 1 && (tokenURINonEmpty ? (keccak256(bytes(observed)) == keccak256(bytes(tokenURI))) : (bytes(observed).length > 0)));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function holding test logic
    function run(string calldata name_, string calldata tokenURI, bool finiteSupply, bool transferable, uint256 itemsRemaining, uint256 itemPrice, uint16 dailyAllowance) public payable {
        // The harness deployer of C is the owner and thus an admin, so no extra setup required.
        uint256 beforeCount = c.uniqueTokensOutstanding();

        // top-level state-changing call as required
        c.createGameItem(name_, tokenURI, finiteSupply, transferable, itemsRemaining, itemPrice, dailyAllowance);

        uint256 afterCount = c.uniqueTokensOutstanding();
        uint256 newId = beforeCount; // new token id is previous count

        string memory observed = c.uri(newId);

        bool tokenURINonEmpty = bytes(tokenURI).length > 0;
        bool observedEqualsProvided = keccak256(bytes(observed)) == keccak256(bytes(tokenURI));
        bool observedIsNonEmpty = bytes(observed).length > 0;

        // GENERAL RULE asserted:
        // uniqueTokensOutstanding increased by exactly 1, AND
        // if caller provided a non-empty tokenURI then uri(newId) equals it, otherwise uri(newId) is non-empty (base uri)
        assert(afterCount == beforeCount + 1 && (tokenURINonEmpty ? observedEqualsProvided : observedIsNonEmpty));
    }

    receive() external payable {}
}
